const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const HOURS = [14, 15, 16, 17, 18];
const status = document.getElementById("status");
let state;
let today;
const pad = (n) => String(n).padStart(2, "0");
// The day offset days from today, as YYYY-MM-DD with its weekday.
const dayAt = (offset) => {
  const [y, m, d] = today.split("-").map(Number);
  const at = new Date(Date.UTC(y, m - 1, d + offset));
  return { date: at.toISOString().slice(0, 10), weekday: at.getUTCDay() };
};
// Every slot in the next three weeks, Monday to Thursday, kept off the days the rules rule out.
const slots = () => {
  const ruled = new Set(state.data.rules.map((rule) => rule.weekday));
  const all = [];
  for (let i = 0; i < 21; i += 1) {
    const day = dayAt(i);
    if (day.weekday < 1 || day.weekday > 4 || ruled.has(day.weekday)) continue;
    for (const hour of HOURS) all.push({ at: day.date + "T" + pad(hour) + ":00", weekday: day.weekday });
  }
  return all;
};
// Each booking in its slot: a fixed one where it asked, if that slot is open; the rest in the
// first free slots, in the order they were booked. No slot holds two.
const placed = () => {
  const available = slots();
  const free = new Set(available.map((slot) => slot.at));
  const where = new Map();
  for (const booking of state.data.bookings) {
    if (booking.at && free.has(booking.at)) {
      where.set(booking.id, booking.at);
      free.delete(booking.at);
    }
  }
  for (const booking of state.data.bookings) {
    if (where.has(booking.id)) continue;
    const next = available.find((slot) => free.has(slot.at));
    if (!next) continue;
    where.set(booking.id, next.at);
    free.delete(next.at);
  }
  return where;
};
const label = (at) => {
  const [date, time] = at.split("T");
  const [y, m, d] = date.split("-").map(Number);
  return DAYS[new Date(Date.UTC(y, m - 1, d)).getUTCDay()] + " " + date + ", " + time;
};
const render = () => {
  const where = placed();
  const booked = state.data.bookings
    .filter((booking) => where.has(booking.id))
    .sort((a, b) => where.get(a.id).localeCompare(where.get(b.id)));
  document.getElementById("sessions").replaceChildren(...booked.map((booking) => {
    const item = document.createElement("li");
    item.dataset.hook = "session";
    const time = document.createElement("time");
    time.dateTime = where.get(booking.id);
    time.textContent = label(where.get(booking.id));
    const name = document.createElement("span");
    name.dataset.hook = "session-task";
    name.textContent = booking.name;
    item.append(time, " ", name);
    return item;
  }));
  document.getElementById("rules").replaceChildren(...state.data.rules.map((rule) => {
    const item = document.createElement("li");
    item.dataset.hook = "rule";
    item.textContent = DAYS[rule.weekday] + " ";
    const remove = document.createElement("button");
    remove.type = "button";
    remove.dataset.hook = "rule-remove";
    remove.textContent = "Teach on " + DAYS[rule.weekday] + " again";
    remove.addEventListener("click", () =>
      save([{ op: "remove", collection: "rules", id: rule.id, revisionCount: state.revisions.rules[rule.id] }], "Removed."),
    );
    item.append(remove);
    return item;
  }));
};
const load = () => tessera.call("data.read").then((read) => { state = read; render(); });
const save = (operations, said) =>
  tessera.call("data.patch", { operations }).then(load).then(
    () => { status.textContent = said; },
    () => { status.textContent = "That wasn't saved. Try again."; return load(); },
  );
tessera.call("clock.now").then((now) => { today = now.date; return load(); });
document.querySelector("[data-hook=task-add]").addEventListener("click", () => {
  const field = document.querySelector("[data-hook=task-name]");
  const name = field.value.trim();
  if (!name) { status.textContent = "Write the student's name first."; return; }
  field.value = "";
  save([{ op: "add", collection: "bookings", record: { name } }], name + " is booked.");
});
document.querySelector("[data-hook=rule-add]").addEventListener("click", () => {
  const weekday = Number(document.querySelector("[data-hook=rule-day]").value);
  if (state.data.rules.some((rule) => rule.weekday === weekday)) return;
  save([{ op: "add", collection: "rules", record: { weekday } }], "Added.");
});
